", direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_basic/disclosure-widget--framework-vanilla-js--style-dark/google/gemini-3-flash-preview__s3/script.js', full_command_text=None, hook_message=None, intention='Edit file', new_file_contents="document.addEventListener('DOMContentLoaded', () => {
    const disclosures = document.querySelectorAll('.example');

    disclosures.forEach(disclosure => {
        const button = disclosure.querySelector('button[aria-expanded]');
        const details = disclosure.querySelector('.details');

        // Initial state: ensure details are hidden if button is not expanded
        if (button.getAttribute('aria-expanded') === 'false') {
            details.style.display = 'none';
        }

        button.addEventListener('click', () => {
            const isExpanded = button.getAttribute('aria-expanded') === 'true';
            const nextState = !isExpanded;

            button.setAttribute('aria-expanded', nextState);

            if (nextState) {
                // Expanding
                details.style.display = 'block';
                // Trigger reflow
                details.offsetHeight;
                details.style.maxHeight = '500px';
                details.style.padding = '1rem 1.5rem 1.5rem';
            } else {
                // Collapsing
                details.style.maxHeight = '0';
                details.style.padding = '0 1.5rem';

                // Wait for transition
                const transitionEndHandler = () => {
                    if (button.getAttribute('aria-expanded') === 'false') {
                        details.style.display = 'none';
                    }
                    details.removeEventListener('transitionend', transitionEndHandler);
                };
                details.addEventListener('transitionend', transitionEndHandler);
            }
        });
    });
});
