", direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_basic/disclosure-widget--framework-vanilla-js--style-dark/google/gemini-3-flash-preview__s3/style.css', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents=':root {
    --bg-color: #121212;
    --container-bg: #1e1e1e;
