body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: radial-gradient(circle at center, #1a1a2e 0%, #121212 100%);
    color: var(--text-color);
    line-height: 1.7;
    margin: 0;
    padding: 2rem;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
}

header {
    margin-top: 2rem;
    margin-bottom: 3rem;
    text-align: center;
}

h1 {
    color: var(--accent-color);
    font-size: 3rem;
    letter-spacing: -0.02em;
    margin-bottom: 0.5rem;
    text-shadow: 0 0 20px rgba(187, 134, 252, 0.3);
}

header::after {
    content: '';
    display: block;
    width: 60px;
    height: 4px;
    background: var(--accent-color);
    margin: 1.5rem auto;
    border-radius: 2px;
}

main {
    width: 100%;
    max-width: 800px;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: var(--bg-color);
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
    text-decoration: none;
    font-weight: bold;
}

.skip-link:focus {
    top: 0;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.example {
    background-color: var(--container-bg);
    border: 1px solid rgba(255, 255, 255, 0.05);
    border-radius: 12px;
    margin-bottom: 1.25rem;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
}

.example:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 15px rgba(0, 0, 0, 0.4);
    border-color: rgba(187, 134, 252, 0.3);
}

button[aria-expanded] {
    width: 100%;
    padding: 1.25rem 1.5rem;
    background: none;
    border: none;
    color: var(--text-color);
    font-size: 1.2rem;
    font-weight: 600;
    text-align: left;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: background-color 0.2s ease;
}

button[aria-expanded]:hover {
    background-color: var(--hover-bg);
}

button[aria-expanded]:focus-visible {
    outline: 2px solid var(--focus-outline);
    outline-offset: -2px;
}

.icon::before {
    content: '+';
    font-size: 1.5rem;
    color: var(--accent-color);
    transition: transform 0.3s ease;
    display: inline-block;
}

button[aria-expanded="true"] .icon::before {
    content: '-';
    transform: rotate(180deg);
}

.details {
    padding: 0 1.5rem;
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease-out, padding 0.3s ease;
    background-color: rgba(255, 255, 255, 0.02);
}

.details[hidden] {
    display: none;
}

button[aria-expanded="true"] + .details {
    max-height: 500px; /* Large enough to fit content */
    padding: 1rem 1.5rem 1.5rem;
}

footer {
    margin-top: 3rem;
    font-size: 0.9rem;
    color: #888;
}

@media (max-width: 600px) {
    body {
        padding: 1rem;
    }
    h1 {
        font-size: 1.8rem;
    }
}
